import React from 'react'
import { connect } from 'react-redux'
import { Row, Col, Spin, Button, notification } from 'antd'
import { get } from 'lodash'
import { formInitialData, finalEditPayloadMapper } from './tableDataformation'
import FieldItem from '../PolicyCreationAttributes/fieldItem'
import actions from '../../../../../../redux/productConfig/actions'
import { localStorageCheck } from '../../../../util/localstorageCheck'

const {
  getAllProductAttributes,
  addProductAttributesAction,
  resetProductConfigRedux
} = actions
class EditAttributes extends React.Component {
  state = {
    packageCode: '',
    initialData: [],
    formData: {},
    step1Data: {},
    templateData: [],
    initialDataCopy: [],
    loading: false,
    buttonDisabled: false,
    isEndorsement: false
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      templateData,
      templateDatamessage,
      addProductAttributes
    } = nextProps
    if (templateDatamessage === 'success') {
      this.setState({
        templateData: get(templateData, 'data.details', [])
      })
      this.props.resetProductConfigRedux(['templateDatamessage'])
    }
    if (addProductAttributes === 'success') {
      notification.success({
        message: 'Success',
        description: 'Product attributes created successfully'
      })
      this.props.resetProductConfigRedux(['addProductAttributes'])
      this.props.history.goBack()
    }
    if (addProductAttributes !== 'success' && addProductAttributes !== undefined) {
      notification.error({
        message: 'Error',
        description: get(addProductAttributes, 'errors[0].description', '')
      })
      this.setState({
        loading: false
      })
      this.props.resetProductConfigRedux(['addProductAttributes'])
    }
  }

  componentDidMount () {
    const { location } = this.props
    const formName = get(location, 'state.formName', '')
    switch (formName) {
      case 'detail-page-attributes': {
        const formData = get(location, 'state.formData.val', {})
        const initialData = formInitialData(formData)
        this.setState({
          step1Data: get(location, 'state.formData.step1Data', {}),
          initialData,
          initialDataCopy: initialData,
          formData
        })
        this.props.getAllProductAttributes()
      }
        break
      default: {
        this.props.history.goBack()
      }
    }
  }

  updateDataHandler = (data) => {
    const modifiedData = data
    modifiedData[modifiedData.length - 1] = {
      ...modifiedData[modifiedData.length - 1],
      showAddButton: true
    }
    this.setState({
      initialData: modifiedData
    })
    data.forEach(item => {
      const className = get(item, 'className')
      const itemType = get(item, 'type')
      const tableData = get(item, 'tableData', [])
      if (className === 'child' && itemType === 'object' && tableData.length === 0) {
        this.setState({
          buttonDisabled: true
        })
      } else {
        this.setState({
          buttonDisabled: false
        })
      }
    })
  }

  handleAddAttributes =() => {
    const { initialDataCopy, step1Data, formData } = this.state
    this.setState({
      loading: true
    })
    const productCode = get(step1Data, 'code', '')
    const submittedData = localStorageCheck(window.sessionStorage.getItem('nestedAttributes')) || {}
    const addedData = finalEditPayloadMapper(submittedData)
    const copyData = finalEditPayloadMapper(initialDataCopy)
    const filteredData = addedData.filter(ad => !copyData.find(cd => ad.attribute_id === cd.attribute_id))
    const mappedPayload = filteredData.map(fd => ({
      ...fd,
      attribute_type: formData.attribute_type
    }))

    this.props.addProductAttributesAction({
      query: { productCode: productCode },
      body: {
        payload: mappedPayload,
        type: 'edit'
      }
    })
  }

  handleCancelAdd = () => {
    window.sessionStorage.removeItem('nestedAttributes')
    this.props.history.goBack()
  }

  componentWillUnmount () {
    window.sessionStorage.removeItem('nestedAttributes')
  }

  render () {
    const { initialData, templateData, loading, buttonDisabled } = this.state
    const onlyRegular = initialData.length > 0 && initialData[0].parent_attribute_id === null
    return (
      <>
        <Spin spinning={loading} loading='Edit Page Loading...'>
          <Row type='flex' justify='center' align='middle'>
            <Col span={24}>
              <Spin spinning={templateData.length === 0 && initialData.length === 0} tip='Loading...'>
                {
                  initialData.map((item, index) => {
                    return (
                      <FieldItem
                        index={item.id}
                        key={item.id}
                        item={item}
                        onlyRegular={onlyRegular}
                        parentData={initialData}
                        step2Data={initialData}
                        templateData={templateData}
                        updateData={this.updateDataHandler}
                      />
                    )
                  })
                }
              </Spin>
            </Col>
          </Row>
          <Row type='flex' justify='center' gutter={50}>
            <Col>
              <Button onClick={this.handleCancelAdd}>Cancel</Button>
            </Col>
            <Col>
              <Button disabled={buttonDisabled} type='primary' onClick={this.handleAddAttributes}>Submit</Button>
            </Col>
          </Row>
        </Spin>
      </>
    )
  }
}

export default connect(
  state => ({
    addProductAttributes: state.ProductConfigurable.addProductAttributesMessage,
    templateData: state.ProductConfigurable.getAllProductAttributes,
    templateDatamessage: state.ProductConfigurable.getAllProductAttributesMessage
  }), {
    getAllProductAttributes,
    resetProductConfigRedux,
    addProductAttributesAction
  }
)(EditAttributes)
